import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"资源消耗 & 冷却时间","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills-cost.md","filePath":"guide/skills-cost.md","lastUpdated":1787389693000}'),o={name:"guide/skills-cost.md"};function s(n,t,l,h,i,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="资源消耗-冷却时间" tabindex="-1">资源消耗 &amp; 冷却时间 <a class="header-anchor" href="#资源消耗-冷却时间" aria-label="Permalink to &quot;资源消耗 &amp; 冷却时间&quot;">​</a></h1><h2 id="资源消耗" tabindex="-1">资源消耗 <a class="header-anchor" href="#资源消耗" aria-label="Permalink to &quot;资源消耗&quot;">​</a></h2><p>主动战技、爆发技、魔法具有资源消耗，也就是<strong>爆发能量</strong>和<strong>魔法消耗</strong>，若角色的对应能力值不足，将<strong>无法释放技能</strong>。</p><table tabindex="0"><thead><tr><th>技能类型</th><th>消耗资源</th><th>不足时</th></tr></thead><tbody><tr><td>主动战技</td><td>爆发能量</td><td>无法释放</td></tr><tr><td>爆发技</td><td>爆发能量（通常 ≥ 100）</td><td>无法释放</td></tr><tr><td>魔法</td><td>魔法值</td><td>无法释放</td></tr></tbody></table><h2 id="冷却时间" tabindex="-1">冷却时间 <a class="header-anchor" href="#冷却时间" aria-label="Permalink to &quot;冷却时间&quot;">​</a></h2><p>主动战技、爆发技、魔法具有<strong>冷却时间</strong>：在释放技能后的一段时间内，角色<strong>无法再次释放</strong>此技能。</p><h2 id="减耗与冷却缩减" tabindex="-1">减耗与冷却缩减 <a class="header-anchor" href="#减耗与冷却缩减" aria-label="Permalink to &quot;减耗与冷却缩减&quot;">​</a></h2><p><strong>智力属性</strong>（或者等效的技能或物品）提供的减耗可以降低资源消耗和冷却时间：</p><table tabindex="0"><thead><tr><th>减免项</th><th>每 1 点智力</th></tr></thead><tbody><tr><td>魔法消耗减少</td><td>0.125%</td></tr><tr><td>爆发能量消耗减少</td><td>0.075%</td></tr><tr><td>冷却缩减</td><td>0.25%</td></tr></tbody></table><blockquote><p>减耗与冷却缩减的来源不限于智力属性本身——等效的技能或物品同样可以施加这些减免。</p></blockquote>',10)])])}const b=a(o,[["render",s]]);export{_ as __pageData,b as default};
